import React, {useState,useEffect } from 'react'
import Navbar from '../components/Navbar'
import Footer from '../components/Footer'
import Card from '../components/Card'
import Carousel from '../components/Carousel'

export default function Home() {
     
    const [foodCat, setfoodCat] = useState([]);
    const [foodItem, setfoodItem] = useState([]);

   const loadData = async () => {
    let response = await fetch("http://localhost:5000/api/data", {
        method:"POST",
        headers:{
            'Content-Type': 'application/json'
        }
    });
 
    response = await response.json();

    // Use object keys instead of array indices
    // console.log(response.food_items, response.foodCategory);
    setfoodItem(response.foodItem);
    setfoodCat(response.foodCat);
}
useEffect(() => {
    loadData();
}, []);

    return (
        <div>

            <div> <Navbar /></div>
            <div> <Carousel /> </div>
            

                <div className='container' > 
                    {
                        foodCat !==[]
                        ? foodCat.map((data)=>{
                            return (
                                <div>Hello World </div>
                            )
                        }):<div> """"""""""</div>
                    }
                    <Card />
                    </div>
        
            <div> <Footer /> </div>

        </div>
    )
}
